function dump(node, depth) {
  const info = {
    id: node.id, name: node.name, type: node.type,
    w: Math.round(node.width), h: Math.round(node.height),
  };
  if ('fills' in node) info.fills = JSON.stringify(node.fills).slice(0, 300);
  if ('strokes' in node && node.strokes && node.strokes.length) info.strokes = JSON.stringify(node.strokes).slice(0, 200);
  if ('strokeWeight' in node) info.strokeWeight = node.strokeWeight;
  if (node.type === 'TEXT') {
    info.chars = node.characters;
    info.font = node.fontName.family + '/' + node.fontName.style;
    info.size = node.fontSize;
  }
  if ('layoutMode' in node && node.layoutMode !== 'NONE') {
    info.layout = node.layoutMode; info.gap = node.itemSpacing; info.pad = [node.paddingLeft, node.paddingTop, node.paddingRight, node.paddingBottom];
  }
  if ('cornerRadius' in node) info.radius = node.cornerRadius;
  let out = JSON.stringify(info);
  if (depth > 0 && 'children' in node) {
    for (const c of node.children) out += '\n' + '  '.repeat(3 - depth + 1) + dump(c, depth - 1);
  }
  return out;
}
