function tree(n, d) {
  let s = '';
  const pad = '  '.repeat(d);
  const sz = (n.width !== undefined) ? ` [${Math.round(n.width)}x${Math.round(n.height)}]` : '';
  const txt = n.type === 'TEXT' ? ` "${(n.characters||'').slice(0,30)}"` : '';
  s += `${pad}${n.type}${sz} ${n.name}${txt}\n`;
  if (n.children) for (const c of n.children) s += tree(c, d+1);
  return s;
}
const ids = ['7:77','7:94','7:62','7:64','7:68','7:136','7:99'];
