function mkT(parent, name, chars, font, size, w, h) {
  const t = figma.createText();
  t.fontName = font; t.fontSize = size; t.characters = chars;
  t.fills = [{ type: 'SOLID', color: INK }];
  t.textAutoResize = 'NONE'; t.resize(w, h);
  t.name = name; parent.appendChild(t); return t;
}
function setText(node, chars, font) {
  if (!node) return;
  node.characters = chars;
  if (font) node.fontName = font;
}

/* ---------- helpers to build sections ---------- */
function sectionFrame(name, w, h, padL, padR, padT, padB, mode, spacing) {
  const f = figma.createFrame();
  f.name = name; f.resize(w, h);
  f.fills = [];
  f.layoutMode = mode || 'VERTICAL';
  f.primaryAxisSizingMode = 'AUTO';
  f.counterAxisSizingMode = 'AUTO';
  if (padL !== undefined) { f.paddingLeft = padL; f.paddingRight = padR; f.paddingTop = padT; f.paddingBottom = padB; }
  if (spacing !== undefined) f.itemSpacing = spacing;
  return f;
}

